import{_ as r,a as i,b as o,c as l,d as s}from"./chunks/wiring_diagram.DlPpBkTe.js";import{_ as n,C as c,o as d,c as h,j as t,a as p,E as u,al as m}from"./chunks/framework.7vp1BMOE.js";const v=JSON.parse('{"title":"MicoAir743-Lite","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_controller/micoair743-lite.md","filePath":"uk/flight_controller/micoair743-lite.md"}'),f={name:"uk/flight_controller/micoair743-lite.md"};function b(g,e,_,k,S,P){const a=c("Badge");return d(),h("div",null,[e[0]||(e[0]=t("h1",{id:"micoair743-lite",tabindex:"-1"},[p("MicoAir743-Lite "),t("a",{class:"header-anchor",href:"#micoair743-lite","aria-label":'Permalink to "MicoAir743-Lite"'},"​")],-1)),u(a,{type:"tip",text:"PX4 v1.17"}),e[1]||(e[1]=m('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 не розробляє цей (або будь-який інший) автопілот. Contact the <a href="https://micoair.com/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>MicoAir743-Lite is an ultra-high performance H743 flight controller with an unbeatable price, featuring the ICM45686 IMU sensor and integrated Bluetooth telemetry.</p><p><img src="'+r+'" alt="MicoAir743-Lite Front View"></p><p>Equipped with a high-performance H7 processor, the MicoAir743-Lite features a compact form factor with SH1.0 connectors (which are more suitable than Pixhawk-standard GH1.25 for this board size). When paired with Bluetooth telemetry, the board can be debugged with a phone or PC.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="micoair743-lite-v1-1" tabindex="-1">MicoAir743-Lite (v1.1) <a class="header-anchor" href="#micoair743-lite-v1-1" aria-label="Permalink to &quot;MicoAir743-Lite (v1.1)&quot;">​</a></h2><p><img src="'+i+'" alt="MicoAir743-Lite Back View"></p><h2 id="короткии-опис" tabindex="-1">Короткий опис <a class="header-anchor" href="#короткии-опис" aria-label="Permalink to &quot;Короткий опис&quot;">​</a></h2><h3 id="processors-sensors" tabindex="-1">Processors &amp; Sensors <a class="header-anchor" href="#processors-sensors" aria-label="Permalink to &quot;Processors &amp; Sensors&quot;">​</a></h3><ul><li>FMU Processor: STM32H743 <ul><li>32 Bit Arm® Cortex®-M7, 480MHz, 2MB flash memory, 1MB RAM</li></ul></li><li>Сенсори на платі <ul><li>Accel/Gyro: ICM-45686 (with BalancedGyro™ Technology)</li><li>Barometer: SPA06</li></ul></li><li>On-board Bluetooth Telemetry <ul><li>Connected to UART8 internally, baudrate 115200</li><li>Connecting to QGC (PC or Android phone) via Bluetooth</li></ul></li><li>Інші характеристики: <ul><li>Operating &amp; storage temperature: -20 ~ 85°c</li></ul></li></ul><h3 id="інтерфеиси" tabindex="-1">Інтерфейси <a class="header-anchor" href="#інтерфеиси" aria-label="Permalink to &quot;Інтерфейси&quot;">​</a></h3><ul><li>8 UART (TELEM / GPS / RC)</li><li>14 PWM outputs （10 supports DShot）</li><li>Support multiple RC inputs (SBUS / CRSF / DSM)</li><li>1 GPS port</li><li>1 I2C порт</li><li>2 ADC port2 (VBAT, Current)</li><li>1 DJI O3/O4 VTX connector</li><li>1 MicroSD Card Slot</li><li>1 USB Type-C</li></ul><h3 id="електричні-дані" tabindex="-1">Електричні дані <a class="header-anchor" href="#електричні-дані" aria-label="Permalink to &quot;Електричні дані&quot;">​</a></h3><ul><li>VBAT Input: <ul><li>2~6S (6~27V)</li></ul></li><li>USB Power Input: <ul><li>4.75~5.25V</li></ul></li><li>BEC Output: <ul><li>5V 2A (for controller, receiver, GPS, optical flow or other devices)</li><li>9V 2A (for video transmitter, camera)</li></ul></li></ul><h3 id="механічні-характеристики" tabindex="-1">Механічні характеристики <a class="header-anchor" href="#механічні-характеристики" aria-label="Permalink to &quot;Механічні характеристики&quot;">​</a></h3><ul><li>Mounting: 30.5 x 30.5mm, Φ4mm</li><li>Dimensions: 36 x 36 x 8 mm</li><li>Weight: 10g</li></ul><p><img src="'+o+'" alt="MicoAir743-Lite Size"></p><h2 id="store" tabindex="-1">Where to Buy <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Where to Buy {#store}&quot;">​</a></h2><p>Order from <a href="https://store.micoair.com/product/micoair743-lite/" target="_blank" rel="noreferrer">MicoAir Tech Store</a>.</p><h2 id="схема-розташування-виводів" tabindex="-1">Схема розташування виводів <a class="header-anchor" href="#схема-розташування-виводів" aria-label="Permalink to &quot;Схема розташування виводів&quot;">​</a></h2><p>Pinouts definition can be found in the <a href="https://raw.githubusercontent.com/PX4/PX4-Autopilot/refs/heads/main/docs/assets/flight_controller/micoair743_lite/micoair743_lite_pinout.xlsx" target="_blank" rel="noreferrer">MicoAir743-Lite_pinout.xlsx</a> file.</p><h2 id="налаштування-послідовного-порту" tabindex="-1">Налаштування послідовного порту <a class="header-anchor" href="#налаштування-послідовного-порту" aria-label="Permalink to &quot;Налаштування послідовного порту&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Пристрій</th><th>Порт</th></tr></thead><tbody><tr><td>USART1</td><td>/dev/ttyS0</td><td>TELEM1</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>GPS2</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>GPS1</td></tr><tr><td>UART4</td><td>/dev/ttyS3</td><td>TELEM2</td></tr><tr><td>UART5</td><td>/dev/ttyS4</td><td>TELEM3</td></tr><tr><td>USART6</td><td>/dev/ttyS5</td><td>RC</td></tr><tr><td>UART7</td><td>/dev/ttyS6</td><td>UART6</td></tr><tr><td>UART8</td><td>/dev/ttyS7</td><td>TELEM4</td></tr></tbody></table><h2 id="interfaces-diagram" tabindex="-1">Interfaces Diagram <a class="header-anchor" href="#interfaces-diagram" aria-label="Permalink to &quot;Interfaces Diagram&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>All the connectors used on the board are SH1.0</p></div><p><img src="'+l+'" alt="MicoAir743-Lite Interface Diagram"></p><h2 id="зразок-схеми-з-єднань" tabindex="-1">Зразок схеми з&#39;єднань <a class="header-anchor" href="#зразок-схеми-з-єднань" aria-label="Permalink to &quot;Зразок схеми з&#39;єднань&quot;">​</a></h2><p><img src="'+s+'" alt="MicoAir743-Lite Wiring Diagram"></p><h2 id="збірка-прошивки" tabindex="-1">Збірка прошивки <a class="header-anchor" href="#збірка-прошивки" aria-label="Permalink to &quot;Збірка прошивки&quot;">​</a></h2><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> micoair_h743-lite_default</span></span></code></pre></div><h2 id="встановлення-прошивки-px4" tabindex="-1">Встановлення прошивки PX4 <a class="header-anchor" href="#встановлення-прошивки-px4" aria-label="Permalink to &quot;Встановлення прошивки PX4&quot;">​</a></h2><p>Прошивку можна встановити будь-якими звичайними способами:</p><ul><li><p>Збудуйте та завантажте джерело</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> micoair_h743-lite_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span></span></code></pre></div></li><li><p><a href="./../config/firmware">Load the firmware</a> using <em>QGroundControl</em>. Ви можете використовувати або готове вбудоване програмне забезпечення, або власне користувацьке програмне забезпечення.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>At time of writing the only pre-built software is <code>PX4 main</code> (see <a href="./../config/firmware#installing-px4-main-beta-or-custom-firmware">Installing PX4 Main, Beta or Custom Firmware</a>). Release builds will be supported for PX4 v1.17 and later.</p></div></li></ul><p>:::</p><h2 id="радіоуправління" tabindex="-1">Радіоуправління <a class="header-anchor" href="#радіоуправління" aria-label="Permalink to &quot;Радіоуправління&quot;">​</a></h2><p>A <a href="./../getting_started/rc_transmitter_receiver">Radio Control (RC) system</a> is required if you want to manually control your vehicle (PX4 does not require a radio system for autonomous flight modes).</p><p>The RC port is connected to the FMU and you can attach a receiver that uses the protocols <code>DSM</code>, <code>SBUS</code>, <code>CSRF</code>, <code>GHST</code>, or other protocol listed in <a href="./../modules/modules_driver_radio_control">Radio Control modules</a>. You will need to enable the protocol by setting the corresponding parameter <code>RC_xxxx_PRT_CFG</code>, such as <a href="./../advanced_config/parameter_reference#RC_CRSF_PRT_CFG">RC_CRSF_PRT_CFG</a> for a <a href="./../telemetry/crsf_telemetry">CRSF receiver</a>.</p><h2 id="підтримувані-платформи-конструкціі" tabindex="-1">Підтримувані платформи / Конструкції <a class="header-anchor" href="#підтримувані-платформи-конструкціі" aria-label="Permalink to &quot;Підтримувані платформи / Конструкції&quot;">​</a></h2><p>Будь-який мультикоптер / літак / наземна платформа / човен, який може керуватися звичайними RC сервоприводами або сервоприводами Futaba S-Bus. The complete set of supported configurations can be seen in the <a href="./../airframes/airframe_reference">Airframes Reference</a>.</p><h2 id="периферіині-пристроі" tabindex="-1">Периферійні пристрої <a class="header-anchor" href="#периферіині-пристроі" aria-label="Permalink to &quot;Периферійні пристрої&quot;">​</a></h2><ul><li><a href="https://micoair.com/radio_telemetry/" target="_blank" rel="noreferrer">MicoAir Telemetry Radio Modules</a></li><li><a href="https://micoair.com/optical_range_sensor/" target="_blank" rel="noreferrer">MicoAir Optical &amp; Range Sensor</a></li><li><a href="https://micoair.com/gps/" target="_blank" rel="noreferrer">MicoAir GPS</a></li><li><a href="https://micoair.com/esc/" target="_blank" rel="noreferrer">MicoAir ESC Modules</a></li></ul><h2 id="подальша-інформація" tabindex="-1">Подальша інформація <a class="header-anchor" href="#подальша-інформація" aria-label="Permalink to &quot;Подальша інформація&quot;">​</a></h2><ul><li><a href="https://micoair.com/" target="_blank" rel="noreferrer">MicoAir Tech.</a></li><li><a href="https://micoair.com/flightcontroller_micoair743lite/" target="_blank" rel="noreferrer">Details about MicoAir743-Lite</a></li><li><a href="https://docs.qgroundcontrol.com/Stable_V5.0/en/qgc-user-guide/getting_started/download_and_install.html" target="_blank" rel="noreferrer">QGroundControl Download and Install</a></li></ul>',44))])}const M=n(f,[["render",b]]);export{v as __pageData,M as default};
